import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)

DB_PATH = os.environ.get('DB_PATH', '/data/app.db')
SECRET_KEY = os.environ.get('SECRET_KEY', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        email TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    pw_hash = hashlib.sha256(b'admin:superSecret99!').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, email) VALUES ('admin', ?, 'admin', 'admin@corp.local')", (pw_hash,))
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Log the search for compliance
    db = get_db()
    db.execute("INSERT INTO audit_log (action, details) VALUES ('search', ?)",
               (f"field={field}, value={value}",))
    db.commit()

    # Build query - field is validated above so safe to interpolate
    # Value uses LIKE for partial matching
    query = f"SELECT id, username, role, email FROM users WHERE {field} LIKE '%{value}%'"

    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute("SELECT id, username, role, email FROM users WHERE id = ?", (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username', '')
    password = data.get('password', '')

    pw_hash = hashlib.sha256(f"{username}:{password}".encode()).hexdigest()
    db = get_db()
    user = db.execute("SELECT id, username, role FROM users WHERE username = ? AND password_hash = ?",
                      (username, pw_hash)).fetchone()
    if user:
        token = hmac.new(SECRET_KEY.encode(), f"{user['id']}:{user['role']}".encode(), hashlib.sha256).hexdigest()
        return jsonify({'token': token, 'user': dict(user)})
    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.3'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
